["Onion Rings"]={description="Now that the Star Onion Brigade has the old Optistery ring, they can unlock the door to the spooky old abandoned Ghosty House. Yikes! Once inside, will they be able to uncover the Cat Burglar's plot and foil her evil scheme? Go, go, Onions!",fame="Windurst",fame_level="3",id=42,next={"Crying Over Onions"},previous={"Inspector's Gadget!"},requirements={{count=1,id=130,ki=true,name="[Key Item] Old ring"}},reward="Bouncer Club",start_npc="Kohlo-Lakolo",start_pos="G-5",start_zone="Port Windurst",title="Star Onion Brigadier"},
["Orastery Woes"]={description="The Operations Division of the Orastery has asked you to assist them in their plan to deliver the ministry from misery. Use the magical club that you have been given to record combat information for the Orastery.",fame="Windurst",id=86,reward="Black Halo weapon skill",start_npc="Kuroido-Moido",start_pos="E-7",start_zone="Port Windurst"},
["Overnight Delivery"]={description="You couldn't quite make out what Kenapa-Keppa was trying to say, but you guess he wants you to go pick up something from Mhaura. This doesn't look like your ordinary delivery job...?",fame="Windurst",fame_level="2",id=15,next={"Water Way to Go!"},previous={"Food for Thought"},reward="Power Gi",start_npc="Kenapa-Keppa",start_pos="J-9",start_zone="Windurst Waters South"},
